"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { ArrowRight, Check, FlaskConical } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Alert } from "@/components/ui/alert";
import { useLanguage } from "@/hooks/use-language";
import { cn } from "@/lib/utils";
import {
  createDemoAuthAdapter,
  createProviderSignInRunner,
  DemoAuthError,
  SOCIAL_AUTH_PROVIDERS,
  type AuthAdapter,
  type AuthIntent,
  type ProviderSignInHandler,
  type ProviderSignInResult,
  type SocialAuthProvider,
} from "@/lib/demo-auth";

export const socialProviderNames: Record<SocialAuthProvider, string> = {
  google: "Google",
  github: "GitHub",
  microsoft: "Microsoft",
};

/** Inline provider marks; no external assets, SDKs or provider requests. */
export function SocialProviderLogo({
  provider,
}: {
  provider: SocialAuthProvider;
}) {
  return (
    <svg
      role="img"
      aria-label={socialProviderNames[provider]}
      focusable="false"
      viewBox="0 0 24 24"
      className="size-5 shrink-0"
    >
      {provider === "google" ? (
        <>
          <path
            fill="#4285F4"
            d="M21.6 12.23c0-.71-.06-1.39-.18-2.05H12v3.88h5.38a4.6 4.6 0 0 1-2 3.02v2.51h3.24c1.9-1.75 2.98-4.32 2.98-7.36Z"
          />
          <path
            fill="#34A853"
            d="M12 22c2.7 0 4.96-.9 6.62-2.41l-3.24-2.51c-.9.6-2.05.97-3.38.97-2.6 0-4.8-1.75-5.59-4.1H3.07v2.59A10 10 0 0 0 12 22Z"
          />
          <path
            fill="#FBBC05"
            d="M6.41 13.95A6 6 0 0 1 6.1 12c0-.68.12-1.34.31-1.95V7.46H3.07A10 10 0 0 0 2 12c0 1.62.39 3.15 1.07 4.54l3.34-2.59Z"
          />
          <path
            fill="#EA4335"
            d="M12 5.95c1.47 0 2.79.51 3.82 1.5l2.87-2.87A9.6 9.6 0 0 0 12 2a10 10 0 0 0-8.93 5.46l3.34 2.59c.79-2.35 2.99-4.1 5.59-4.1Z"
          />
        </>
      ) : provider === "github" ? (
        <path
          fill="currentColor"
          d="M12 .3a12 12 0 0 0-3.8 23.4c.6.1.8-.3.8-.6v-2.2c-3.3.7-4-1.4-4-1.4-.5-1.4-1.3-1.8-1.3-1.8-1.1-.7.1-.7.1-.7 1.2.1 1.8 1.2 1.8 1.2 1.1 1.8 2.8 1.3 3.5 1 .1-.8.4-1.3.8-1.6-2.7-.3-5.5-1.3-5.5-5.9 0-1.3.5-2.4 1.2-3.2-.1-.3-.5-1.5.1-3.2 0 0 1-.3 3.3 1.2a11.4 11.4 0 0 1 6 0c2.3-1.5 3.3-1.2 3.3-1.2.6 1.7.2 2.9.1 3.2.8.8 1.2 1.9 1.2 3.2 0 4.6-2.8 5.6-5.5 5.9.4.4.8 1.1.8 2.2v3.3c0 .3.2.7.8.6A12 12 0 0 0 12 .3Z"
        />
      ) : (
        <>
          <path fill="#F25022" d="M2 2h9.5v9.5H2z" />
          <path fill="#7FBA00" d="M12.5 2H22v9.5h-9.5z" />
          <path fill="#00A4EF" d="M2 12.5h9.5V22H2z" />
          <path fill="#FFB900" d="M12.5 12.5H22V22h-9.5z" />
        </>
      )}
    </svg>
  );
}

export interface SocialAuthProps {
  intent?: AuthIntent;
  consent?: boolean;
  disabled?: boolean;
  authAdapter?: AuthAdapter;
  /** Overrides authAdapter. The default adapter is entirely local and mock. */
  onProviderSignIn?: ProviderSignInHandler;
  /** UI disclosure; defaults to true when no integration is supplied. */
  demo?: boolean;
  onConsentRequired?: () => void;
  onComplete?: (result: ProviderSignInResult) => void;
  /** Explicit continuation only; this component never opens an OAuth URL. */
  onContinue?: (result: ProviderSignInResult) => void;
  continueLabel?: string;
  className?: string;
}

type SocialAuthState =
  | { phase: "idle" }
  | { phase: "busy"; provider: SocialAuthProvider }
  | { phase: "error"; provider: SocialAuthProvider; consentRequired: boolean }
  | {
      phase: "complete";
      provider: SocialAuthProvider;
      result: ProviderSignInResult;
    };

export function SocialAuth({
  intent = "sign-in",
  consent = false,
  disabled = false,
  authAdapter,
  onProviderSignIn,
  demo = !authAdapter && !onProviderSignIn,
  onConsentRequired,
  onComplete,
  onContinue,
  continueLabel,
  className,
}: SocialAuthProps) {
  const { l } = useLanguage();
  const headingId = useId();
  const disclosureId = useId();
  const defaultAdapter = useMemo(() => createDemoAuthAdapter(), []);
  const runner = useMemo(() => createProviderSignInRunner(), []);
  const pendingRequest = useRef<AbortController | null>(null);
  const [state, setState] = useState<SocialAuthState>({ phase: "idle" });
  const handler: ProviderSignInHandler =
    onProviderSignIn ??
    ((request) => (authAdapter ?? defaultAdapter).signInWithProvider(request));

  useEffect(() => {
    return () => {
      pendingRequest.current?.abort();
    };
  }, []);

  async function signIn(provider: SocialAuthProvider) {
    if (disabled || runner.pending || state.phase === "complete") return;
    const controller = new AbortController();
    pendingRequest.current = controller;
    setState({ phase: "busy", provider });
    try {
      const result = await runner.signIn(
        { provider, intent, consent, signal: controller.signal },
        handler,
      );
      if (!result || controller.signal.aborted) return;
      setState({ phase: "complete", provider, result });
      onComplete?.(result);
    } catch (error) {
      if (controller.signal.aborted) return;
      const consentRequired =
        error instanceof DemoAuthError && error.code === "consent-required";
      setState({ phase: "error", provider, consentRequired });
      if (consentRequired) onConsentRequired?.();
    } finally {
      if (pendingRequest.current === controller) pendingRequest.current = null;
    }
  }

  return (
    <section
      aria-labelledby={headingId}
      aria-describedby={disclosureId}
      aria-busy={state.phase === "busy"}
      className={cn(
        "mt-7 rounded-2xl border border-border bg-background/65 p-3.5 shadow-[0_14px_40px_-30px_var(--primary)] sm:p-4",
        className,
      )}
    >
      <div className="mb-3 flex items-center justify-between gap-3">
        <h2 id={headingId} className="text-xs font-semibold">
          {l("Continue with a provider", "Continuar con un proveedor")}
        </h2>
        <span className="inline-flex items-center gap-1.5 rounded-full border border-primary/20 bg-primary/10 px-2 py-1 text-[10px] font-semibold text-primary">
          <FlaskConical className="size-3" aria-hidden="true" />
          {demo ? l("Demo", "Demo") : l("Adapter", "Adaptador")}
        </span>
      </div>
      <p
        id={disclosureId}
        className="mb-4 text-xs leading-5 text-muted-foreground"
      >
        {demo
          ? l(
              "Local preview. No connection to your provider account.",
              "Vista previa local. No se conecta con tu cuenta del proveedor.",
            )
          : l(
              "Your app handles provider requests and any server session.",
              "Tu aplicación gestiona al proveedor y la sesión del servidor.",
            )}
      </p>
      {state.phase === "complete" ? (
        <div className="grid gap-3">
          <Alert
            variant="success"
            title={
              state.result.kind === "demo"
                ? l(
                    `${socialProviderNames[state.provider]} demo ready`,
                    `Demo de ${socialProviderNames[state.provider]} lista`,
                  )
                : l(
                    "Provider callback complete",
                    "Callback del proveedor listo",
                  )
            }
          >
            {state.result.kind === "demo"
              ? state.result.persistence === "memory"
                ? l(
                    "Browser storage is unavailable. You can continue; this preview will not persist after leaving.",
                    "El almacenamiento del navegador no está disponible. Puedes continuar; la vista previa no se guardará al salir.",
                  )
                : l(
                    "Only a local demo profile was saved. No real provider session was created.",
                    "Solo se guardó un perfil de demostración local. No se creó una sesión real con el proveedor.",
                  )
              : l(
                  "Your application controls the next step. This UI does not verify authentication.",
                  "Tu aplicación controla el siguiente paso. Esta interfaz no verifica la autenticación.",
                )}
          </Alert>
          {state.result.kind === "demo" && onContinue && (
            <Button
              type="button"
              className="min-h-11 w-full"
              onClick={() => onContinue(state.result)}
            >
              <Check className="size-4" aria-hidden="true" />
              {continueLabel ??
                l("Continue to workspace", "Continuar al espacio")}
              <ArrowRight className="size-4" aria-hidden="true" />
            </Button>
          )}
        </div>
      ) : (
        <div className="grid gap-2.5">
          {SOCIAL_AUTH_PROVIDERS.map((provider) => {
            const loading =
              state.phase === "busy" && state.provider === provider;
            const label = l(
              `Continue with ${socialProviderNames[provider]}`,
              `Continuar con ${socialProviderNames[provider]}`,
            );
            return (
              <Button
                key={provider}
                type="button"
                variant="outline"
                loading={loading}
                disabled={disabled || state.phase === "busy"}
                aria-label={label}
                aria-describedby={disclosureId}
                onClick={() => void signIn(provider)}
                className="group min-h-12 w-full justify-start gap-3 border-border/85 px-3 text-sm hover:border-primary/45 hover:shadow-[0_8px_24px_-16px_var(--primary)] motion-safe:hover:-translate-y-0.5"
                style={{
                  backgroundImage:
                    "linear-gradient(115deg, color-mix(in srgb, var(--primary) 5%, var(--surface)), var(--surface) 78%)",
                }}
              >
                {!loading && (
                  <span className="grid size-8 shrink-0 place-items-center rounded-lg border border-border/70 bg-background text-foreground">
                    <SocialProviderLogo provider={provider} />
                  </span>
                )}
                <span className="min-w-0 flex-1 text-left">
                  {loading
                    ? l(
                        `Preparing ${socialProviderNames[provider]}…`,
                        `Preparando ${socialProviderNames[provider]}…`,
                      )
                    : label}
                </span>
                <ArrowRight
                  className="size-3.5 text-muted-foreground transition-transform motion-safe:group-hover:translate-x-0.5"
                  aria-hidden="true"
                />
              </Button>
            );
          })}
          {state.phase === "busy" && (
            <p role="status" className="text-xs text-muted-foreground">
              {demo
                ? l(
                    "Preparing a local demo profile…",
                    "Preparando un perfil local de demostración…",
                  )
                : l("Waiting for your adapter…", "Esperando al adaptador…")}
            </p>
          )}
          {state.phase === "error" && (
            <Alert
              variant="destructive"
              title={l("Could not continue", "No se pudo continuar")}
            >
              <p>
                {state.consentRequired
                  ? l(
                      "Accept the demo terms, then try again.",
                      "Acepta los términos de demostración e inténtalo de nuevo.",
                    )
                  : l(
                      "The provider flow did not finish. Please try again.",
                      "El flujo del proveedor no se completó. Inténtalo de nuevo.",
                    )}
              </p>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                disabled={disabled}
                className="mt-2 h-auto min-h-9 px-2 text-destructive-foreground"
                onClick={() => void signIn(state.provider)}
              >
                {l("Try again", "Intentar de nuevo")}
              </Button>
            </Alert>
          )}
        </div>
      )}
    </section>
  );
}

import * as React from "react";
import { Info, CircleCheck, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
export function Alert({
  title,
  children,
  variant = "info",
  className,
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "success" | "warning" | "destructive";
  className?: string;
}) {
  const Icon =
    variant === "success"
      ? CircleCheck
      : variant === "warning" || variant === "destructive"
        ? TriangleAlert
        : Info;
  return (
    <div
      role={variant === "destructive" ? "alert" : "status"}
      className={cn(
        "flex gap-3 rounded-lg border p-4 text-xs",
        variant === "warning"
          ? "border-warning-foreground/20 bg-warning text-warning-foreground"
          : variant === "destructive"
            ? "border-destructive-foreground/20 bg-destructive text-destructive-foreground"
            : "border-primary/15 bg-accent text-accent-foreground",
        className,
      )}
    >
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div>
        <p className="font-semibold">{title}</p>
        {children && <div className="mt-1 leading-relaxed">{children}</div>}
      </div>
    </div>
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

"use client";
import { useLocale, useTranslations } from "next-intl";
import { useCallback } from "react";
import type { Locale } from "@/i18n/messages";
export function useLanguage() {
  const locale = useLocale() as Locale;
  const common = useTranslations("common");
  const l = useCallback(
    (en: string, es: string) => (locale === "es" ? es : en),
    [locale],
  );
  const number = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) =>
      new Intl.NumberFormat(
        locale === "es" ? "es-CO" : "en-US",
        options,
      ).format(value),
    [locale],
  );
  const currency = useCallback(
    (value: number) =>
      number(value, {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0,
      }),
    [number],
  );
  const date = useCallback(
    (value: Date | string, options?: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(
        locale === "es" ? "es-CO" : "en-US",
        options ?? { month: "short", day: "numeric", year: "numeric" },
      ).format(
        new Date(
          typeof value === "string" && value.length === 10
            ? `${value}T12:00:00`
            : value,
        ),
      ),
    [locale],
  );
  return { locale, common, l, number, currency, date };
}

export const DEMO_AUTH_SESSION_KEY = "aureform:demo-session";
export const SOCIAL_AUTH_PROVIDERS = ["google", "github", "microsoft"] as const;

export type SocialAuthProvider = (typeof SOCIAL_AUTH_PROVIDERS)[number];
export type AuthIntent = "sign-in" | "sign-up";
export type DemoAuthProvider = SocialAuthProvider | "email" | "otp";

/** Local display data only. This is never proof of identity or authorization. */
export interface DemoAuthSession {
  version: 1;
  demo: true;
  provider: DemoAuthProvider;
  name: string;
  email: string;
  createdAt: string;
}

export type DemoAuthStorage = Pick<Storage, "setItem">;
export type DemoAuthPersistence = "local" | "memory";

export interface ProviderSignInRequest {
  provider: SocialAuthProvider;
  intent: AuthIntent;
  /** Required for sign-up, including when a consumer injects its own adapter. */
  consent: boolean;
  /** Abort pending work when the UI is unmounted; check before side effects. */
  signal?: AbortSignal;
}

export type ProviderSignInResult =
  | {
      kind: "demo";
      session: DemoAuthSession;
      persistence: DemoAuthPersistence;
    }
  | {
      /** The consumer owns authentication, its server session and any redirect. */
      kind: "handled";
    };

/**
 * Inject from a Client Component. Return `handled` when your application owns
 * the flow, or `demo` for local preview data. Never return passwords or tokens.
 * Reject to display a retryable error; raw exception messages are not rendered.
 */
export type ProviderSignInHandler = (
  request: ProviderSignInRequest,
) => Promise<ProviderSignInResult>;

export interface AuthAdapter {
  signInWithProvider: ProviderSignInHandler;
}

type DemoAuthErrorCode =
  | "consent-required"
  | "invalid-request"
  | "invalid-session"
  | "aborted"
  | "busy";

export class DemoAuthError extends Error {
  readonly code: DemoAuthErrorCode;

  constructor(code: DemoAuthErrorCode) {
    super(`Demo auth: ${code}`);
    this.name = "DemoAuthError";
    this.code = code;
  }
}

export function validateProviderSignInRequest(request: ProviderSignInRequest) {
  if (
    !SOCIAL_AUTH_PROVIDERS.includes(request.provider) ||
    !["sign-in", "sign-up"].includes(request.intent)
  ) {
    throw new DemoAuthError("invalid-request");
  }
  if (request.intent === "sign-up" && request.consent !== true) {
    throw new DemoAuthError("consent-required");
  }
  if (request.signal?.aborted) throw new DemoAuthError("aborted");
}

function safeDemoSession(session: DemoAuthSession): DemoAuthSession {
  if (
    session?.version !== 1 ||
    session.demo !== true ||
    ![...SOCIAL_AUTH_PROVIDERS, "email", "otp"].includes(session.provider) ||
    typeof session.name !== "string" ||
    !session.name.trim() ||
    session.name.length > 160 ||
    typeof session.email !== "string" ||
    !session.email.trim() ||
    session.email.length > 254 ||
    typeof session.createdAt !== "string" ||
    !Number.isFinite(Date.parse(session.createdAt))
  ) {
    throw new DemoAuthError("invalid-session");
  }
  // Reconstruct an allowlist rather than serializing an adapter's object.
  return {
    version: 1,
    demo: true,
    provider: session.provider,
    name: session.name.trim(),
    email: session.email.trim(),
    createdAt: session.createdAt,
  };
}

export function createDemoAuthSession(
  provider: DemoAuthProvider,
  identity?: { name?: string; email?: string },
): DemoAuthSession {
  return safeDemoSession({
    version: 1,
    demo: true,
    provider,
    name: identity?.name || "Alex Morgan",
    email:
      identity?.email ||
      (SOCIAL_AUTH_PROVIDERS.includes(provider as SocialAuthProvider)
        ? `alex.${provider}@example.com`
        : "alex.morgan@example.com"),
    createdAt: new Date().toISOString(),
  });
}

/**
 * Only the session allowlist is written. SecurityError, quota errors, SSR and
 * explicit `null` storage fall back to the result held in component memory.
 */
export function persistDemoAuthSession(
  session: DemoAuthSession,
  storage?: DemoAuthStorage | null,
): DemoAuthPersistence {
  const safeSession = safeDemoSession(session);
  try {
    const target =
      storage === undefined
        ? typeof window === "undefined"
          ? null
          : window.localStorage
        : storage;
    if (!target) return "memory";
    target.setItem(DEMO_AUTH_SESSION_KEY, JSON.stringify(safeSession));
    return "local";
  } catch {
    return "memory";
  }
}

export function waitForDemoAuth(
  milliseconds = 350,
  signal?: AbortSignal,
): Promise<void> {
  if (signal?.aborted) return Promise.reject(new DemoAuthError("aborted"));
  return new Promise((resolve, reject) => {
    const abort = () => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      reject(new DemoAuthError("aborted"));
    };
    const timer = setTimeout(
      () => {
        signal?.removeEventListener("abort", abort);
        resolve();
      },
      Math.max(0, milliseconds),
    );
    signal?.addEventListener("abort", abort, { once: true });
  });
}

/** No network calls, OAuth navigation, cookies, passwords or access tokens. */
export function createDemoAuthAdapter({
  storage,
  delayMs = 350,
}: {
  storage?: DemoAuthStorage | null;
  delayMs?: number;
} = {}): AuthAdapter {
  return {
    async signInWithProvider(request) {
      validateProviderSignInRequest(request);
      await waitForDemoAuth(delayMs, request.signal);
      if (request.signal?.aborted) throw new DemoAuthError("aborted");
      const session = createDemoAuthSession(request.provider);
      return {
        kind: "demo",
        session,
        persistence: persistDemoAuthSession(session, storage),
      };
    },
  };
}

/**
 * One in-flight request per UI instance, including injected adapters. Duplicate
 * calls return null, validation happens before the callback, and failure unlocks
 * retries. This guard is UX behavior, never a server authorization check.
 */
export function createProviderSignInRunner() {
  let pending = false;
  return {
    get pending() {
      return pending;
    },
    async signIn(
      request: ProviderSignInRequest,
      handler: ProviderSignInHandler,
    ): Promise<ProviderSignInResult | null> {
      if (pending) return null;
      validateProviderSignInRequest(request);
      pending = true;
      try {
        const result = await handler(request);
        if (request.signal?.aborted) throw new DemoAuthError("aborted");
        if (result?.kind === "handled") return { kind: "handled" };
        if (
          result?.kind !== "demo" ||
          !["local", "memory"].includes(result.persistence)
        ) {
          throw new DemoAuthError("invalid-session");
        }
        const session = safeDemoSession(result.session);
        if (session.provider !== request.provider) {
          throw new DemoAuthError("invalid-session");
        }
        return {
          kind: "demo",
          session,
          persistence: result.persistence,
        };
      } finally {
        pending = false;
      }
    },
  };
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .af-gradient-border {
    border-color: color-mix(in srgb, var(--primary) 40%, var(--border));
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary) 18%, transparent);
  }

  .af-card {
    --tw-shadow: var(--af-card-shadow, var(--af-shadow-soft));
    background-color: var(--af-card-background, var(--surface));
    background-image: var(--af-card-image, none);
    -webkit-backdrop-filter: var(--af-card-blur, none);
    backdrop-filter: var(--af-card-blur, none);
    border-radius: var(--af-radius, 16px);
    transition:
      border-color var(--af-motion-hover) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      background-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-card-flat {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: 0 0 #0000;
    --af-card-blur: none;
  }
  .af-card-elevated {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
  }
  .af-card-glass {
    --af-card-background: var(--af-glass-background);
    --af-card-image: linear-gradient(130deg, color-mix(in srgb, var(--primary) 8%, transparent), transparent 65%);
    --af-card-shadow: var(--af-shadow-soft);
    --af-card-blur: blur(var(--af-glass-blur));
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .af-card-gradient {
    --af-card-background: var(--surface);
    --af-card-image: linear-gradient(135deg, var(--surface) 25%, color-mix(in srgb, var(--af-color-primary) 20%, var(--surface)));
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }

  .af-control-solid { background-image: none; }
  .af-control-gradient {
    background-color: var(--primary);
    background-image: var(--af-gradient-primary);
    color: var(--primary-foreground);
    --tw-shadow: var(--af-shadow-soft);
  }
  .af-control-gradient:hover:not(:disabled,[data-disabled]) {
    --tw-shadow: var(--af-glow);
  }
  .af-control-soft {
    background-color: var(--accent);
    background-image: none;
    color: var(--accent-foreground);
    border: 1px solid color-mix(in srgb, var(--primary) 24%, var(--border));
  }
  .af-control-outline {
    background-color: var(--surface);
    background-image: none;
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
    --tw-shadow: 0 0 #0000;
  }
  .af-control-glass {
    background-color: var(--af-glass-background);
    background-image: linear-gradient(120deg, color-mix(in srgb, var(--primary) 10%, transparent), transparent);
    backdrop-filter: blur(var(--af-glass-blur));
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
  }

  .af-badge-solid, .af-badge-gradient {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  .af-badge-gradient { background-image: var(--af-gradient-primary); }
  .af-badge-soft { background-color: var(--accent); color: var(--accent-foreground); }
  .af-badge-outline { background-color: transparent; color: var(--foreground); border: 1px solid var(--border); }
  .af-badge-glass { background-color: var(--af-glass-background); color: var(--foreground); border: 1px solid var(--border); backdrop-filter: blur(12px); }

  .af-button-destructive[data-appearance] {
    color: var(--destructive-foreground);
    background-color: var(--destructive);
    background-image: none;
    border-color: color-mix(in srgb, var(--destructive-foreground) 45%, var(--border));
  }
  .af-button[data-disabled], .af-button:disabled {
    background-image: none;
    backdrop-filter: none;
  }

  .af-input, .af-textarea {
    border-color: color-mix(in srgb, var(--muted-foreground) 48%, var(--surface));
  }
}

[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card),
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::before,
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .af-button,
  .af-button::before,
  .af-button::after,
  .af-button[aria-busy="true"] > svg,
  .af-hover-card,
  .af-hover-card::before,
  .af-hover-card::after,
  .af-hover-link,
  .af-hover-link::before,
  .af-hover-link::after {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    translate: none !important;
  }
}
